import {PLANS,comparePlans,formatTime} from './model.mjs';
import {esc,num,money,pill,btn,kv,metric,card,metrics,road,events,signs,queueChart,costChart,schedule} from './visuals.mjs';
const body=s=>`<div class="card-body">${s}</div>`;
const field=(key,label,value,min,max,step=1,help='')=>`<div class="field"><label for="${key}">${label}</label><input id="${key}" data-assumption="${key}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"><small>${help}</small></div>`;
const check=(key,label,value)=>`<label style="display:flex;align-items:center;gap:8px;font-size:13px"><input data-assumption="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const rail=s=>`<section class="card event-rail"><div class="card-head"><h2>Live event feed</h2><span class="tag" data-live="eventcount">${s.events.length} ACTIVE</span></div><div data-live="events">${events(s)}</div></section>`;
export function workerSummary(s,st){return `${pill(s.worker.status)}<div class="big-number">${num(s.worker.continuous)} <small style="font-size:16px">min</small></div><p class="sub">Continuous duty / ${st.assumptions.breakThreshold}-min reminder</p><div class="progress"><i style="width:${Math.min(100,s.worker.continuous/st.assumptions.breakThreshold*100)}%;background:${s.worker.fatigue?'var(--orange)':'var(--green)'}"></i></div>${kv('Time to zone entry',s.worker.ttc==null?'No valid approach':`${num(s.worker.ttc,1)} s`)}${kv('Synthetic track source',s.feed?'Available':'Unavailable')}`;}
export function queue(s,st){return `<div class="metric-grid">${metric('Queue length',`${num(s.queue.length)} <small>m</small>`,'7 m equivalent space per vehicle','')}${metric('Growth rate',`${num(s.queue.growth,1)} <small>m/min</small>`,'Constant demand and capacity','')}${metric('Tail position',s.feed?`${num(s.queue.tail)} <small>m</small>`:'UNKNOWN',s.traffic.beyondNetwork?'Tail extends beyond model boundary':'Relative to model origin','')}${metric('Linked state',s.queue.status.toUpperCase(),'Warning / speed / operator event','',s.queue.status==='high'?'red':'')}</div><div class="two-columns">${card('Queue evolution','Both plans use identical demand and analysis duration',body(`<div data-live="queuechart">${queueChart(s,st.assumptions)}</div><div class="mini-stats" data-live="balance">${balance(s)}</div><p class="note">Planning estimates remain available during a sensor outage. Fractional vehicle counts are expected in this fluid queue model.</p>`))}${card('Connected roadside outputs','Virtual VMS + speed sign + operator notification',`<div data-live="signs">${signs(s)}</div>${body(`<div class="actions">${btn('Inject demand surge','surge','primary')}${btn(st.feed?'Disconnect sensor':'Restore sensor','feed')}</div><p class="note">These outputs are simulated. The demo never sends commands to roadside equipment. Thresholds below are examples, not approved road settings.</p>`)}`)}</div><div class="section-gap">${card('Operator playbook','One state drives all three outputs',`<div class="table-scroll"><table><thead><tr><th>Demo condition</th><th>VMS / virtual speed</th><th>Operator action</th></tr></thead><tbody><tr><td>Queue &lt; 70 m</td><td>ROADWORKS / 80 km/h</td><td>Monitor feed and verify equipment.</td></tr><tr><td>Queue ≥ 70 m</td><td>SLOW TRAFFIC / 60 km/h</td><td>Check the queue tail and upstream warning coverage.</td></tr><tr><td>Queue ≥ 200 m</td><td>QUEUE AHEAD / 40 km/h</td><td>Acknowledge, assess approaching traffic and escalate via the site procedure.</td></tr><tr><td>Sensor unavailable</td><td>DATA LOST / no speed command</td><td>Manual verification required; do not infer a clear road.</td></tr></tbody></table></div>`)}<p class="footnote">Queue length = max(0, arrivals − departures) × 7 m. Growth assumes constant demand; this is a demonstrator, not calibrated traffic forecasting.</p></div>`;}
export function balance(s){return `<div><span>Model arrivals</span><strong>${num(s.traffic.arrivals,1)}</strong></div><div><span>Model departures</span><strong>${num(s.traffic.served,1)}</strong></div><div><span>Queued vehicles</span><strong>${num(s.traffic.queue,1)}</strong></div>`;}
export function planning(s,st){const a=st.assumptions,c=comparePlans(a);return `<div class="two-columns">${card('Configure the work-zone model','Cremorne example · queue, access and delivery assumptions',body(`<div class="form-grid">${field('demand','Traffic demand (vehicles / hour)',a.demand,0,2400,50)}${field('horizon','Analysis window (seconds)',a.horizon,60,3600,60)}${field('extraBarriers','Additional barriers',a.extraBarriers,0,80,1,'Each adds 380 kg to dispatch loads.')}${kv('Active plan',`Plan ${st.plan}`)}</div><div class="actions section-gap">${check('pedClosed','Close alternative pedestrian link',a.pedClosed)}${check('busClosed','Close bus diversion',a.busClosed)}</div><p class="note">Capacity is an explicit assumption: A = 1,050 veh/h; B = 1,350 veh/h. Walking speed = 1.2 m/s; bus detour speed = 25 km/h. Fixed schematic network; no live map service.</p>`))}${card('From road design to deliveries','Change equipment → change payload checks',`<div class="table-scroll"><table><thead><tr><th>Equipment</th><th>Need / stock</th><th>Load</th></tr></thead><tbody>${s.fleet.equipment.items.map(e=>`<tr><td>${e.type}</td><td class="${e.quantity>e.stock?'red':''}">${e.quantity} / ${e.stock}</td><td>${num(e.quantity*e.unitKg)} kg</td></tr>`).join('')}</tbody></table></div>${body(`<p class="sub">${num(s.fleet.equipment.totalKg)} kg creates the barrier, sign and VMS jobs in Fleet & charging. Two fixed service / collection jobs complete the working day.</p>${btn('Inspect delivery feasibility','nav-fleet','small')}`)}`)}</div><div class="comparison-grid section-gap">${c.map(x=>`<article class="plan-card ${x.plan===s.plan?'chosen':''}"><h3>Plan ${x.plan} · ${PLANS[x.plan].name}${pill(x.feasible?'clear':'high',x.feasible?'MODEL FEASIBLE':'CONSTRAINTS')}</h3><p>${PLANS[x.plan].description}</p>${kv(`Queue after ${a.horizon/60} min`,`${num(x.traffic.length)} m`)}${kv('Observed wait / arrival',`${num(x.traffic.observedWaitPerArrival/60,1)} min`)}${kv('Pedestrian extra distance',x.traffic.pedestrian.reachable?`${x.traffic.pedestrian.extraMeters} m`:'NO CONNECTED ROUTE')}${kv('Bus extra time',x.traffic.bus.reachable?`${num(x.traffic.bus.extraSeconds/60,1)} min`:'NO CONNECTED ROUTE')}${kv('Equipment weight',`${num(x.fleet.equipment.totalKg)} kg`)}${kv('Dispatch after search',x.fleet.feasible?`${x.fleet.changes.length} job reassignment(s)`:'Unresolved constraints')}<div class="actions section-gap">${btn(x.plan===s.plan?'Active plan':`Use Plan ${x.plan}`,`plan-${x.plan}`,x.plan===s.plan?'':'primary',x.plan===s.plan?'disabled':'')}</div></article>`).join('')}</div><div class="alert-banner info section-gap">${c.every(x=>x.feasible)?'Plan B reduces the modelled queue and walking detour, but requires more barriers and an extra VMS trailer. The trade-off flows through to delivery loads.':'A plan with disconnected access, unavailable inventory or infeasible dispatch is flagged. Better traffic flow alone does not make a plan feasible.'}</div><p class="footnote">Observed wait is cumulative waiting inside the analysis window divided by arrivals. It is not a full-trip travel time. Bus impact adds detour travel to the end-of-window queue clearance estimate. Plan comparison evaluates optimized dispatch; the supporting tools use your selected dispatch mode.</p>`;}
export function fleet(s,st){const f=s.fleet,a=st.assumptions,c=s.cost;return `<div class="metric-grid">${metric('Dispatch status',f.feasible?'FEASIBLE':'REVIEW',`${f.changes.length} job changes · ${num(f.totalKm)} km total`,'',f.feasible?'green':'orange')}${metric('EV end-of-day energy',`${num(f.vehicles[0].finalKwh,1)} <small>kWh</small>`,`${num(a.reserveSoc*a.battery)} kWh reserve required`,'','purple')}${metric('Mixed fleet · 5 years',money(c.mixed),'2 diesel + 1 EV + depot charger','TCO')}${metric('Versus 3 new diesel',money(Math.abs(c.saving)),c.saving>=0?'Lower total cost under assumptions':'Higher total cost under assumptions','TCO',c.saving>=0?'green':'orange')}</div><div class="actions" style="margin-bottom:18px">${btn('Find minimum adjustment','optimize','primary')}${btn('Restore original dispatch','unoptimize')}${btn(a.chargerAvailable?'Disable depot charger':'Enable depot charger','charger')}${pill(f.feasible?'clear':'watch',st.optimized?`SEARCHED ${f.searchCount} OPTIONS`:'ORIGINAL DISPATCH')}</div>${st.optimized?`<div class="alert-banner ${f.feasible?'info':'danger'}">${f.feasible?(f.changes.length?f.changes.map(x=>`<strong>${x.jobId}: ${x.from} → ${x.to}</strong>`).join(' · ')+' frees depot time and meets job, payload and reserve constraints.':'The original dispatch is already feasible.'):'No feasible dispatch found within zero-, one- or two-job reassignments. Revise resources or assumptions.'} Search minimizes changed jobs, then maximizes EV distance within that search space.</div>`:''}<div class="two-columns">${card('Delivery & charging schedule','Fixed round trips · 08:00–13:00',schedule(f))}${card('Five-year ownership comparison','Undiscounted AUD · purchase + operation − year-5 resale',costChart(c))}</div><div class="section-gap">${card('Job-level feasibility','Equipment quantities are generated by the active work-zone plan',`<div class="table-scroll"><table><thead><tr><th>Job / route</th><th>Assigned</th><th>Window</th><th>Round trip</th><th>Payload</th><th>Finish energy</th><th>Check</th></tr></thead><tbody>${f.rows.map(j=>`<tr><td><strong>${j.id}</strong> · ${j.label}</td><td>${j.vehicle}${j.vehicle!==j.original?' <span class="tag purple">MOVED</span>':''}</td><td>${formatTime(j.start)}–${formatTime(j.end)}</td><td>${j.km} km</td><td>${num(j.kg)} kg</td><td>${j.afterKwh==null?'Diesel':`${num(j.afterKwh,1)} kWh`}</td><td>${pill(j.energyValid&&j.payloadValid?'clear':'high',j.energyValid&&j.payloadValid?'PASS':'REVIEW')}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="lower-grid">${card('Constraint & charging evidence',`${f.equipment.items.length} equipment types · one shared depot charger`,body(`${f.issues.length?`<ul class="check-list">${f.issues.map(i=>`<li class="red">${esc(i)}</li>`).join('')}</ul>`:'<p class="green">All modelled dispatch constraints pass.</p>'}${f.charges.map(ch=>kv(`Charge ${formatTime(ch.start)}–${formatTime(ch.end)}`,`${num(ch.kwh,1)} battery kWh / ${num(ch.gridKwh,1)} grid kWh`)).join('')}<p class="note">Battery energy = distance × consumption. Charging includes ${(a.chargeEfficiency*100).toFixed(0)}% efficiency. Payload, vehicle compatibility, fixed job windows and reserve are hard checks.</p>`))}${card('Make the business case honest','EV may cost more. Change assumptions and inspect the crossover.',body(`${kv('Diesel baseline, 5 years',money(c.diesel))}${kv('Annual EV distance assumption',`${num(c.evKm)} km`)}${kv('Annual operating costs · diesel / mixed',`${money(c.baselineAnnual)} / ${money(c.mixedAnnual)}`)}<p class="note">Annual mileage is an independent long-term assumption; a one-day reassignment does not silently change TCO. Maintenance: $18,000 / $15,000 per year. Year-5 residual: $60,000 / $80,000. Finance, tax and carbon costs excluded.</p>`))}</div><div class="section-gap">${card('Editable fleet assumptions','Apply on change; invalid values are rejected',body(`<div class="form-grid">${field('electricityCost','Electricity (AUD / grid kWh)',a.electricityCost,.01,2,.01)}${field('dieselCost','Diesel (AUD / litre)',a.dieselCost,.1,6,.1)}${field('evPrice','EV purchase (AUD)',a.evPrice,50000,500000,1000)}${field('dieselPrice','Diesel vehicle purchase (AUD)',a.dieselPrice,30000,300000,1000)}${field('chargerCost','Charger installed (AUD)',a.chargerCost,0,150000,1000)}${field('annualKm','Annual km per vehicle (TCO)',a.annualKm,1000,150000,1000)}${field('chargerPower','Depot charger power (kW)',a.chargerPower,0,350,10)}${field('battery','EV battery capacity (kWh)',a.battery,80,500,10)}${field('consumption','Battery consumption (kWh / km)',a.consumption,.2,4,.1)}${field('chargeEfficiency','Grid-to-battery efficiency',a.chargeEfficiency,.5,1,.01)}${field('initialSoc','Initial battery fraction',a.initialSoc,.2,1,.05)}${field('reserveSoc','Minimum reserve fraction',a.reserveSoc,.05,.4,.05)}</div>`))}</div>`;}
export const VIEWS={queue,planning,fleet};
